window.AUTH=window.AUTH||{};window.AUTH["06-1181"]={"d":"06-1181","id":"2007/06-1181","n":"Dada v. Mukasey","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the respondent","date":"","url":"https://www.justice.gov/osg/media/200676/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/dada-v-mukasey-brief-merits","n":113}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep554/usrep554001/usrep554001.pdf","tr":true,"items":[{"t":"case","label":"Alimi v. Ashcroft","cite":"391 F.3d 888","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/391/888/","by":{"0":"21, 33"}},{"t":"case","label":"Azarte v. Ashcroft","cite":"394 F.3d 1278","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/394/1278/","op":1,"ar":1,"by":{"0":"28, 46"}},{"t":"case","label":"Ballenilla-Gonzalez v. INS","cite":"546 F.2d 515","y":1976,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/546/515/","by":{"0":"13"}},{"t":"case","label":"Banda-Ortiz v. Gonzales","cite":"445 F.3d 387","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/445/387/","op":1,"by":{"0":"13, 14"}},{"t":"case","label":"Bocava v. Gonzales","cite":"412 F.3d 257","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/412/257/","by":{"0":"36"}},{"t":"case","label":"CFTC v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Connecticut Bd. of Pardons v. Dumschat","cite":"452 U.S. 458","y":1981,"id":"1980/79-1997","sc":1,"sum":"The power vested in the Connecticut Board of Pardons to commute sentences conferred no rights on respondents beyond the right to seek commutation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"50"}},{"t":"case","label":"Costello v. INS","cite":"376 U.S. 120","y":1964,"id":"1963/83","sc":1,"op":1,"sum":"Petitioner, while a naturalized citizen, was convicted of two separate offenses involving moral turpitude. Following his subsequent denaturalization on the ground that his citizenship had been acquired by willful misrepresentation, proceedings were brought against him under § 241 (a) (4) of the Immigration and Nationality Act of 1952, which provides for deportation of an alien who at any time after entry \"is …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37, 38"}},{"t":"case","label":"El Himri v. Ashcroft","cite":"344 F.3d 1261","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/344/1261/","by":{"0":"36"}},{"t":"case","label":"Fernandez-Vargas v. Gonzales","cite":"126 S. Ct. 2422","y":2006,"id":"2005/04-1376","sc":1,"sum":"The Court ruled that the reinstatement statute does apply to illegal aliens who re-entered the U.S. before the effective date of the statute, and that the application to such aliens was not impermissibly retroactive.","sumSrc":"Oyez","by":{"0":"3"}},{"t":"case","label":"Foti v. INS","cite":"375 U.S. 217","y":1963,"id":"1963/28","sc":1,"sum":"Under § 106 (a) of the Immigration and Nationality Act, as added in 1961, a Federal Court of Appeals has sole and exclusive jurisdiction to review an administrative determination of the Attorney General denying a suspension of deportation sought by an alien under § 244 (a)(5). Pp. 217-232. 308 F.2d 779, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Garcia-Mateo v. Keisler","cite":"503 F.3d 698","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/503/698/","by":{"0":"20"}},{"t":"case","label":"INS v. Abudu","cite":"485 U.S. 94","y":1988,"id":"1987/86-1128","sc":1,"sum":"Respondent, a native and citizen of Ghana, overstayed his visa. After he pleaded guilty in 1981 to drug charges, deportation proceedings were initiated, at which he expressly declined to seek asylum as a refugee. In 1982, he was ordered deported, and in 1984, the Board of Immigration Appeals (BIA) dismissed his appeal. In 1985, while his petition for review in the Court of Appeals was pending, respondent filed a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"INS v. Aguirre-Aguirre","cite":"526 U.S. 415","y":1999,"id":"1998/97-1754","sc":1,"sum":"The Court noted that withholding of deportation is mandatory if an alien establishes that it is more likely than not that he or she will suffer political persecution if deported.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"op":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"INS v. Doherty","cite":"502 U.S. 314","y":1992,"id":"1991/90-925","sc":1,"sum":"The judgment is reversed. 908 F. 2d 1108, reversed. THE CHIEF JUSTICE delivered the opinion of the Court with respect to Part I, concluding that the Attorney General did not abuse his discreCite as: 502 U. S. 314 (1992) tion in denying the motion to reopen Doherty's deportation proceedings. There is no statutory provision for reopening, and the authority for such motions derives solely from regulations promulgated …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"INS v. Phinpathya","cite":"464 U.S. 183","y":1984,"id":"1983/82-91","sc":1,"sum":"The Court held that the “continuous physical presence” requirement for suspension of deportation in the Immigration and Nationality Act should be interpreted literally.","sumSrc":"Oyez","by":{"0":"9, 17, 50"}},{"t":"case","label":"INS v. Rios-Pineda","cite":"471 U.S. 444","y":1985,"id":"1984/83-2032","sc":1,"sum":"Section 244(a)(1) of the Immigration and Nationality Act allows the Attorney General to suspend an alien's deportation if the alien has been present in the United States for a continuous period of at least seven years, is of good moral character, and demonstrates that deportation would result in extreme hardship to the alien or to the alien's spouse or child, who is a United States citizen. Even if these …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Irwin v. Department of Veterans Affairs","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"sum":"The Supreme Court held that lower courts have consistently held that notice to an attorney's office qualifies as notice to the client. \"The practical effect of a contrary rule would be to encourage factual disputes about when actual notice was received, and thereby create uncertainty in an area of the law where certainty is much to be desired,\" wrote Chief Justice Rehnquist.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Lampf, Pleva , Lipkind , Prupis & Petigrow v. Gilbertson","cite":"501 U.S. 350","y":1991,"id":"1990/90-333","sc":1,"sum":"The judgment is reversed. 895 F. 2d 1416, 1417, and 1418, reversed. JUSTICE BLACKMUN delivered the opinion of the Court with respect to Parts I, II-B, II-C, III, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Long Island Care at Home, Ltd. v. Coke","cite":"127 S. Ct. 2339","y":2007,"id":"2006/06-593","sc":1,"sum":"A unanimous Court ruled that the Department of Labor's regulation was \"valid and binding\" and therefore entitled to all of the deference courts normally give to administrative regulations. The opinion by Justice Stephen Breyer considered the regulation a normal instance of an agency \"filling a statutory gap,\" and rejected each of the lower court's arguments that it was unlawful.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Lopez v. Davis","cite":"531 U.S. 230","y":2000,"id":"2000/99-7504","sc":1,"sum":"The Court held that the categorically denial of early release to a prisoner who committed felony using firearm is a permissible exercise of the BOP's discretion, even if the prisoner has successfully completed a substance abuse program. \"The Bureau reasonably concluded that an inmate's prior involvement with firearms, in connection with the commission of a felony, suggests his readiness to resort to life-endangering violence and therefore appropriately determines the early release decision,\" wrote Justice Ginsburg for the majority.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Lopez-Chavez v. Ashcroft","cite":"383 F.3d 650","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/383/650/","by":{"0":"4, 36"}},{"t":"case","label":"Ngarurih v. Ashcroft","cite":"371 F.3d 182","y":2004,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/371/182/","op":1,"by":{"0":"8, 29, 36"}},{"t":"case","label":"Nwakanma v. Ashcroft","cite":"352 F.3d 325","y":2003,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/352/325/","by":{"0":"36"}},{"t":"case","label":"Obale v. Attorney Gen.","cite":"453 F.3d 151","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/453/151/","op":1,"by":{"0":"36"}},{"t":"case","label":"Pace v. Diguglielmo","cite":"544 U.S. 408","y":2005,"id":"2004/03-9627","sc":1,"sum":"The Court held that the federal statute of limitations barred Pace's petition, as it was filed beyond the deadline. Pace was not entitled to statutory tolling because a petition filed after a time limit, which does meet any exceptions to that limit, was no more \"properly filed\" than a petition filed after a time limit permitting no exception.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Patel v. Gonzales","cite":"470 F.3d 216","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/470/216/","by":{"0":"20"}},{"t":"case","label":"Rife v. Ashcroft","cite":"374 F.3d 606","y":2004,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/374/606/","by":{"0":"36"}},{"t":"case","label":"Salinas v. United States","cite":"522 U.S. 52","y":1997,"id":"1997/96-738","sc":1,"sum":"The Court held that section 666(a)(1)(B) does not require the Government to prove the bribe in question had a demonstrated effect upon federal funds.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Sidikhouya v. Gonzales","cite":"407 F.3d 953","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/407/953/","op":1,"ar":1,"by":{"0":"28"}},{"t":"case","label":"Smiley v. Citibank (S.D.) N.A.","cite":"517 U.S. 735","y":1996,"id":"1995/95-860","sc":1,"op":1,"sum":"Noting the “presumption that Congress, when it left ambiguity in a statute meant for implementation by an agency, understood that the ambiguity would be resolved, ﬁrst and foremost, by the agency”.","sumSrc":"opinion","by":{"0":"48"}},{"t":"case","label":"Stone v. INS","cite":"514 U.S. 386","y":1995,"id":"1994/93-1199","sc":1,"op":1,"ar":1,"sum":"A timely motion for reconsideration of a BIA decision does not toll the running of § 106(a)(1)'s 90-day period.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Thapa v. Gonzales","cite":"460 F.3d 323","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/460/323/","op":1,"by":{"0":"36"}},{"t":"case","label":"Tovar-Landin v. Ashcroft","cite":"361 F.3d 1164","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/361/1164/","by":{"0":"20"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Ugokwe v. United States Att’y Gen.","cite":"453 F.3d 1325","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/453/1325/","op":1,"ar":1,"by":{"0":"28"}},{"t":"case","label":"United States v. Albertini","cite":"472 U.S. 675","y":1985,"id":"1984/83-1624","sc":1,"sum":"Title 18 U. S. C. § 1382 makes it unlawful to reenter a military base after having been \"ordered not to reenter by any officer in command or charge thereof.\" In 1972, respondent received from the commanding officer of Hickam Air Force Base in Hawaii a letter (bar letter) forbidding him to reenter the base without written permission from the commanding officer or his designate. The letter was issued after respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49"}},{"t":"case","label":"United States v. Beggerly","cite":"524 U.S. 38","y":1998,"id":"1997/97-731","sc":1,"sum":"The Court held that the Court of Appeals erred in concluding that this was a sufficient basis to justify reopening the judgment. \"[A]n independent action should be available only to prevent a grave miscarriage of justice,\" wrote Chief Justice Rehnquist, \"it should be obvious that [the Beggerlys'] allegations do not nearly approach this demanding standard.\" The Court also concluded that the Court of Appeals extension of the Quiet Title Act's statutory period by equitable tolling was unwarranted, given its generous nature.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"United States v. Brockamp","cite":"519 U.S. 347","y":1997,"id":"1996/95-1225","sc":1,"op":1,"sum":"The Court ruled that Congress did not intend the \"equitable tolling\" doctrine to apply to the Internal Revenue Code of 1986's time limitations for filing tax refund claims.","sumSrc":"Oyez","by":{"0":"20, 22"}},{"t":"case","label":"United States v. Dieter","cite":"429 U.S. 6","y":1976,"id":"1976/75-1547","sc":1,"sum":"The 30-day limitation period prescribed by the Criminal Appeals Act and Fed. Rule App. Proc. 4 (b) for a Government appeal from an order dismissing an indictment ran from the date of the District Court's denial of the Government's motion to set aside the dismissal of the indictment against respondent, rather than from the date of the dismissal order, and hence the Government's appeal was timely where its notice of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Vidal v. Gonzales","cite":"491 F.3d 250","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/491/250/","by":{"0":"36"}},{"t":"case","label":"Young v. United States","cite":"535 U.S. 43","y":2002,"id":"2001/00-1567","sc":1,"sum":"The Court held section 507(a)(8)(A)(i)'s lookback period is tolled during the pendency of a prior bankruptcy petition. The Court reasoned that the three-year lookback period is a limitations period subject to traditional principles of equitable tolling and that nothing in the Bankruptcy Code precluded the equitable tolling of the lookback period.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"law","label":"Pub. L. No. 107-296","url":"https://www.govinfo.gov/link/plaw/107/public/296","by":{"0":"3"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"27"}},{"t":"usc","label":"8 U.S.C. § 1229c","url":"https://www.law.cornell.edu/uscode/text/8/1229c","subs":["(a)(2)","(b)(2)","(d)","(f)","(a)(1)","(a)(2)(A)","(a)(3)","(b)(1)","(b)(1)(D)","(b)(3)","(d)(1)","(d)(1)(A)","(d)(2)","(d)(3)","(e)","(a)(2)(B)"],"stext":{"head":"§1229c. Voluntary departure","paras":[[0,"(a) Certain conditions"],[0,"(1) In general"],[1,"The Attorney General may permit an alien voluntarily to depart the United States at the alien's own expense under this subsection, in lieu of being subject to proceedings under section 1229a of this title or prior to the completion of such proceedings, if the alien is not deportable under section 1227(a)(2)(A)(iii) or section 1227(a)(4)(B) of this title."],[0,"(2) Period"],[0,"(A) In general"],[2,"Subject to subparagraph (B), permission to depart voluntarily under this subsection shall not be valid for a period exceeding 120 days."],[0,"(B) Three-year pilot program waiver"],[2,"During the period October 1, 2000, through September 30, 2003, and subject to subparagraphs (C) and (D)(ii), the Attorney General may, in the discretion of the Attorney General for humanitarian purposes, waive application of subparagraph (A) in the case of an alien—"],[3,"(i) who was admitted to the United States as a nonimmigrant visitor (described in section 1101(a)(15)(B) of this title) under the provisions of the visa waiver pilot program established pursuant to section 1187 of this title, seeks the waiver for the purpose of continuing to receive medical treatment in the United States from a physician associated with a health care facility, and submits to the Attorney General—"],[4,"(I) a detailed diagnosis statement from the physician, which includes the treatment being sought and the expected time period the alien will be required to remain in the United States;"],[4,"(II) a statement from the health care facility containing an assurance that the alien's treatment is not being paid through any Federal or State public health assistance, that the alien's account has no outstanding balance, and that such facility will notify the Service when the alien is released or treatment is terminated; and"],[4,"(III) evidence of financial ability to support the alien's day-to-day expenses while in the United States (including the expenses of any family member described in clause (ii)) and evidence that any such alien or family member is not receiving any form of public assistance; or"],[3,"(ii) who—"],[4,"(I) is a spouse, parent, brother, sister, son, daughter, or other family member of a principal alien described in clause (i); and"],[4,"(II) entered the United States accompanying, and with the same status as, such principal alien."],[0,"(C) Waiver limitations"],[2,"(i) Waivers under subparagraph (B) may be granted only upon a request submitted by a Service district office to Service headquarters."],[2,"(ii) Not more than 300 waivers may be granted for any fiscal year for a principal alien under subparagraph (B)(i)."],[2,"(iii)(I) Except as provided in subclause (II), in the case of each principal alien described in subparagraph (B)(i) not more than one adult may be granted a waiver under subparagraph (B)(ii)."],[2,"(II) Not more than two adults may be granted a waiver under subparagraph (B)(ii) in a case in which—"],[3,"(aa) the principal alien described in subparagraph (B)(i) is a dependent under the age of 18; or"],[3,"(bb) one such adult is age 55 or older or is physically handicapped."],[0,"(D) Report to Congress; suspension of waiver authority"],[2,"(i) Not later than March 30 of each year, the Commissioner shall submit to the Congress an annual report regarding all waivers granted under subparagraph (B) during the preceding fiscal year."],[2,"(ii) Notwithstanding any other provision of law, the authority of the Attorney General under subparagraph (B) shall be suspended during any period in which an annual report under clause (i) is past due and has not been submitted."],[0,"(3) Bond"],[1,"The Attorney General may require an alien permitted to depart voluntarily under this subsection to post a voluntary departure bond, to be surrendered upon proof that the alien has departed the United States within the time specified."],[0,"(4) Treatment of aliens arriving in the United States"],[1,"In the case of an alien who is arriving in the United States and with respect to whom proceedings under section 1229a of this title are (or would otherwise be) initiated at the time of such alien's arrival, paragraph (1) shall not apply. Nothing in this paragraph shall be construed as preventing such an alien from withdrawing the application for admission in accordance with section 1225(a)(4) of this title."],[0,"(b) At conclusion of proceedings"],[0,"(1) In general"],[1,"The Attorney General may permit an alien voluntarily to depart the United States at the alien's own expense if, at the conclusion of a proceeding under section 1229a of this title, the immigration judge enters an order granting voluntary departure in lieu of removal and finds that—"],[2,"(A) the alien has been physically present in the United States for a period of at least one year immediately preceding the date the notice to appear was served under section 1229(a) of this title;"],[2,"(B) the alien is, and has been, a person of good moral character for at least 5 years immediately preceding the alien's application for voluntary departure;"],[2,"(C) the alien is not deportable under section 1227(a)(2)(A)(iii) or section 1227(a)(4) of this title; and"],[2,"(D) the alien has established by clear and convincing evidence that the alien has the means to depart the United States and intends to do so."],[0,"(2) Period"],[1,"Permission to depart voluntarily under this subsection shall not be valid for a period exceeding 60 days."],[0,"(3) Bond"],[1,"An alien permitted to depart voluntarily under this subsection shall be required to post a voluntary departure bond, in an amount necessary to ensure that the alien will depart, to be surrendered upon proof that the alien has departed the United States within the time specified."],[0,"(c) Aliens not eligible"],[0,"The Attorney General shall not permit an alien to depart voluntarily under this section if the alien was previously permitted to so depart after having been found inadmissible under section 1182(a)(6)(A) of this title."],[0,"(d) Civil penalty for failure to depart"],[0,"(1) In general"],[1,"Subject to paragraph (2), if an alien is permitted to depart voluntarily under this section and voluntarily fails to depart the United States within the time period specified, the alien—"],[2,"(A) shall be subject to a civil penalty of not less than $1,000 and not more than $5,000; and"],[2,"(B) shall be ineligible, for a period of 10 years, to receive any further relief under this section and sections 1229b, 1255, 1258, and 1259 of this title."],[0,"(2) Application of VAWA protections"],[1,"The restrictions on relief under paragraph (1) shall not apply to relief under section 1229b or 1255 of this title on the basis of a petition filed by a VAWA self-petitioner, or a petition filed under section 1229b(b)(2) of this title, or under section 1254(a)(3) of this title (as in effect prior to March 31, 1997), if the extreme cruelty or battery was at least one central reason for the alien's overstaying the grant of voluntary departure."],[0,"(3) Notice of penalties"],[1,"The order permitting an alien to depart voluntarily shall inform the alien of the penalties under this subsection."],[0,"(e) Additional conditions"],[0,"The Attorney General may by regulation limit eligibility for voluntary departure under this section for any class or classes of aliens. No court may review any regulation issued under this subsection."],[0,"(f) Judicial review"],[0,"No court shall have jurisdiction over an appeal from denial of a request for an order of voluntary departure under subsection (b), nor shall any court order a stay of an alien's removal pending consideration of any claim with respect to voluntary departure."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1229c?type=usc&year=mostrecent&link-type=html"},"op":10,"head":"§1229c. Voluntary departure","tname":"Aliens and Nationality","by":{"0":"9, 24, 24, 25, 24, 25, 5, 12, 15, 3, 4, 41, 5, 5, 3, 4, 11, 19, 41, 16, 29, passim, 5, 6, 15, 19, 30, 7, 12, 7, 12, 7, 15, 19, 26, 30, 7, 7, 7, 3, 41, 7, 8, 24, 25, 25"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(2)(B)(i)","(1994)","(b)(1964)","(b)(3)","(b)(3)(B)","(b)(6)"],"by":{"0":"25, 40, 38, 8, 36, 35"}},{"t":"usc","label":"8 U.S.C. § 1252b","url":"https://www.law.cornell.edu/uscode/text/8/1252b","subs":["(e)(2)(A)","(e)(2)(A)(1994)","(f)(2)(1994)"],"by":{"0":"24, 42, 42, 42, 42"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(47)(B)","(a)(47)(B)(i)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"2, 6, 11, 39"}},{"t":"usc","label":"8 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/8/1103","subs":["(a)(1)","(a)(3)"],"by":{"0":"40, 40"}},{"t":"usc","label":"8 U.S.C. § 1105a","url":"https://www.law.cornell.edu/uscode/text/8/1105a","subs":["(a)(3)(1994)","(c)(1994)"],"stext":{"head":"§1105a. Employment authorization for battered spouses of certain nonimmigrants","paras":[[0,"(a) In general"],[0,"In the case of an alien spouse admitted under subparagraph (A), (E)(iii), (G), or (H) of section 1101(a)(15) of this title who is accompanying or following to join a principal alien admitted under subparagraph (A), (E)(iii), (G), or (H) of such section, respectively, the Secretary of Homeland Security may authorize the alien spouse to engage in employment in the United States and provide the spouse with an \"employment authorized\" endorsement or other appropriate work permit if the alien spouse demonstrates that during the marriage the alien spouse or a child of the alien spouse has been battered or has been the subject of extreme cruelty perpetrated by the spouse of the alien spouse. Requests for relief under this section shall be handled under the procedures that apply to aliens seeking relief under section 1154(a)(1)(A)(iii) of this title."],[0,"(b) Construction"],[0,"The grant of employment authorization pursuant to this section shall not confer upon the alien any other form of relief."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1105a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1105a. Employment authorization for battered spouses of certain nonimmigrants","tname":"Aliens and Nationality","by":{"0":"36, 36"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","by":{"0":"2, 7"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(9)(A)","(a)(9)(A)(i)","(a)(9)(A)(ii)","(a)(9)(A)(iii)","(a)(9)(B)(i)(II)","(a)(9)(B)(v)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"29, 2, 3, 2, 3, 3, 29, 30"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(b)(1)(A)"],"by":{"0":"3"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(c)(6)(A)","(c)(7)(A)","(c)(7)(B)","(c)(7)(C)(i)","(c)(7)(C)(ii)","(c)(7)(C)(iv)"],"stext":{"head":"§1229a. Removal proceedings","paras":[[0,"(a) Proceeding"],[0,"(1) In general"],[1,"An immigration judge shall conduct proceedings for deciding the inadmissibility or deportability of an alien."],[0,"(2) Charges"],[1,"An alien placed in proceedings under this section may be charged with any applicable ground of inadmissibility under section 1182(a) of this title or any applicable ground of deportability under section 1227(a) of this title."],[0,"(3) Exclusive procedures"],[1,"Unless otherwise specified in this chapter, a proceeding under this section shall be the sole and exclusive procedure for determining whether an alien may be admitted to the United States or, if the alien has been so admitted, removed from the United States. Nothing in this section shall affect proceedings conducted pursuant to section 1228 of this title."],[0,"(b) Conduct of proceeding"],[0,"(1) Authority of immigration judge"],[1,"The immigration judge shall administer oaths, receive evidence, and interrogate, examine, and cross-examine the alien and any witnesses. The immigration judge may issue subpoenas for the attendance of witnesses and presentation of evidence. The immigration judge shall have authority (under regulations prescribed by the Attorney General) to sanction by civil money penalty any action (or inaction) in contempt of the judge's proper exercise of authority under this chapter."],[0,"(2) Form of proceeding"],[0,"(A) In general"],[2,"The proceeding may take place—"],[3,"(i) in person,"],[3,"(ii) where agreed to by the parties, in the absence of the alien,"],[3,"(iii) through video conference, or"],[3,"(iv) subject to subparagraph (B), through telephone conference."],[0,"(B) Consent required in certain cases"],[2,"An evidentiary hearing on the merits may only be conducted through a telephone conference with the consent of the alien involved after the alien has been advised of the right to proceed in person or through video conference."],[0,"(3) Presence of alien"],[1,"If it is impracticable by reason of an alien's mental incompetency for the alien to be present at the proceeding, the Attorney General shall prescribe safeguards to protect the rights and privileges of the alien."],[0,"(4) Alien's rights in proceeding"],[1,"In proceedings under this section, under regulations of the Attorney General—"],[2,"(A) the alien shall have the privilege of being represented, at no expense to the Government, by counsel of the alien's choosing who is authorized to practice in such proceedings,"],[2,"(B) the alien shall have a reasonable opportunity to examine the evidence against the alien, to present evidence on the alien's own behalf, and to cross-examine witnesses presented by the Government but these rights shall not entitle the alien to examine such national security information as the Government may proffer in opposition to the alien's admission to the United States or to an application by the alien for discretionary relief under this chapter, and"],[2,"(C) a complete record shall be kept of all testimony and evidence produced at the proceeding."],[0,"(5) Consequences of failure to appear"],[0,"(A) In general"],[2,"Any alien who, after written notice required under paragraph (1) or (2) of section 1229(a) of this title has been provided to the alien or the alien's counsel of record, does not attend a proceeding under this section, shall be ordered removed in absentia if the Service establishes by clear, unequivocal, and convincing evidence that the written notice was so provided and that the alien is removable (as defined in subsection (e)(2)). The written notice by the Attorney General shall be considered sufficient for purposes of this subparagraph if provided at the most recent address provided under section 1229(a)(1)(F) of this title."],[0,"(B) No notice if failure to provide address information"],[2,"No written notice shall be required under subparagraph (A) if the alien has failed to provide the address required under section 1229(a)(1)(F) of this title."],[0,"(C) Rescission of order"],[2,"Such an order may be rescinded only—"],[3,"(i) upon a motion to reopen filed within 180 days after the date of the order of removal if the alien demonstrates that the failure to appear was because of exceptional circumstances (as defined in subsection (e)(1)), or"],[3,"(ii) upon a motion to reopen filed at any time if the alien demonstrates that the alien did not receive notice in accordance with paragraph (1) or (2) of section 1229(a) of this title or the alien demonstrates that the alien was in Federal or State custody and the failure to appear was through no fault of the alien."],[2,"The filing of the motion to reopen described in clause (i) or (ii) shall stay the removal of the alien pending disposition of the motion by the immigration judge."],[0,"(D) Effect on judicial review"],[2,"Any petition for review under section 1252 of this title of an order entered in absentia under this paragraph shall (except in cases described in section 1252(b)(5) of this title) be confined to (i) the validity of the notice provided to the alien, (ii) the reasons for the alien's not attending the proceeding, and (iii) whether or not the alien is removable."],[0,"(E) Additional application to certain aliens in contiguous territory"],[2,"The preceding provisions of this paragraph shall apply to all aliens placed in proceedings under this section, including any alien who remains in a contiguous foreign territory pursuant to section 1225(b)(2)(C) of this title."],[0,"(6) Treatment of frivolous behavior"],[1,"The Attorney General shall, by regulation—"],[2,"(A) define in a proceeding before an immigration judge or before an appellate administrative body under this subchapter, frivolous behavior for which attorneys may be sanctioned,"],[2,"(B) specify the circumstances under which an administrative appeal of a decision or ruling will be considered frivolous and will be summarily dismissed, and"],[2,"(C) impose appropriate sanctions (which may include suspension and disbarment) in the case of frivolous behavior."],[1,"Nothing in this paragraph shall be construed as limiting the authority of the Attorney General to take actions with respect to inappropriate behavior."],[0,"(7) Limitation on discretionary relief for failure to appear"],[1,"Any alien against whom a final order of removal is entered in absentia under this subsection and who, at the time of the notice described in paragraph (1) or (2) of section 1229(a) of this title, was provided oral notice, either in the alien's native language or in another language the alien understands, of the time and place of the proceedings and of the consequences under this paragraph of failing, other than because of exceptional circumstances (as defined in subsection (e)(1)) to attend a proceeding under this section, shall not be eligible for relief under section 1229b, 1229c, 1255, 1258, or 1259 of this title for a period of 10 years after the date of the entry of the final order of removal."],[0,"(c) Decision and burden of proof"],[0,"(1) Decision"],[0,"(A) In general"],[2,"At the conclusion of the proceeding the immigration judge shall decide whether an alien is removable from the United States. The determination of the immigration judge shall be based only on the evidence produced at the hearing."],[0,"(B) Certain medical decisions"],[2,"If a medical officer or civil surgeon or board of medical officers has certified under section 1222(b) of this title that an alien has a disease, illness, or addiction which would make the alien inadmissible under paragraph (1) of section 1182(a) of this title, the decision of the immigration judge shall be based solely upon such certification."],[0,"(2) Burden on alien"],[1,"In the proceeding the alien has the burden of establishing—"],[2,"(A) if the alien is an applicant for admission, that the alien is clearly and beyond doubt entitled to be admitted and is not inadmissible under section 1182 of this title; or"],[2,"(B) by clear and convincing evidence, that the alien is lawfully present in the United States pursuant to a prior admission."],[1,"In meeting the burden of proof under subparagraph (B), the alien shall have access to the alien's visa or other entry document, if any, and any other records and documents, not considered by the Attorney General to be confidential, pertaining to the alien's admission or presence in the United States."],[0,"(3) Burden on service in cases of deportable aliens"],[0,"(A) In general"],[2,"In the proceeding the Service has the burden of establishing by clear and convincing evidence that, in the case of an alien who has been admitted to the United States, the alien is deportable. No decision on deportability shall be valid unless it is based upon reasonable, substantial, and probative evidence."],[0,"(B) Proof of convictions"],[2,"In any proceeding under this chapter, any of the following documents or records (or a certified copy of such an official document or record) shall constitute proof of a criminal conviction:"],[3,"(i) An official record of judgment and conviction."],[3,"(ii) An official record of plea, verdict, and sentence."],[3,"(iii) A docket entry from court records that indicates the existence of the conviction."],[3,"(iv) Official minutes of a court proceeding or a transcript of a court hearing in which the court takes notice of the existence of the conviction."],[3,"(v) An abstract of a record of conviction prepared by the court in which the conviction was entered, or by a State official associated with the State's repository of criminal justice records, that indicates the charge or section of law violated, the disposition of the case, the existence and date of conviction, and the sentence."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1229a?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1229a. Removal proceedings","tname":"Aliens and Nationality","by":{"0":"46, 8, 30, 32, 46, 8, 9, 31, 32, 8, 34"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","by":{"0":"12, 2"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(b)(3)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[0,"(A) In general"],[2,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(B) Enforcement by attorney general of a State"],[2,"The attorney general of a State, or other authorized State officer, alleging a violation of the detention requirement under subparagraph (A) that harms such State or its residents shall have standing to bring an action against the Secretary of Homeland Security on behalf of such State or the residents of such State in an appropriate district court of the United States to obtain appropriate injunctive relief. The court shall advance on the docket and expedite the disposition of a civil action filed under this subparagraph to the greatest extent practicable. For purposes of this subparagraph, a State or its residents shall be considered to have been harmed if the State or its residents experience harm, including financial harm in excess of $100."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1231. Detention and removal of aliens ordered removed","tname":"Aliens and Nationality","by":{"0":"7"}},{"t":"usc","label":"8 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/8/1251","subs":["(a)(4)(1964)"],"by":{"0":"37"}},{"t":"usc","label":"8 U.S.C. § 1255","url":"https://www.law.cornell.edu/uscode/text/8/1255","subs":["(a)"],"by":{"0":"12, 2, 50"}},{"t":"usc","label":"8 U.S.C. § 1326","url":"https://www.law.cornell.edu/uscode/text/8/1326","by":{"0":"3"}},{"t":"law","label":"Pub. L. No. 109-162","url":"https://www.govinfo.gov/link/plaw/109/public/162","by":{"0":"7, 25"}},{"t":"reg","label":"59 Fed. Reg. 29,386","url":"https://www.govinfo.gov/link/fr/59/29386","by":{"0":"9"}},{"t":"reg","label":"60 Fed. Reg. 24,574","url":"https://www.govinfo.gov/link/fr/60/24574","by":{"0":"9"}}]};